sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float brightness;
uniform float contrast;

half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) {
        return half4(0.0);
    }
    half3 rgb = c.rgb / c.a;
    rgb = rgb + brightness;
    rgb = (rgb - 0.5) * (1.0 + contrast) + 0.5;
    rgb = clamp(rgb, 0.0, 1.0);
    return half4(rgb * c.a, c.a);
}
